<template><div class="scan"><el-result v-if="error" icon="error" title="设备二维码无效" :sub-title="error"/><template v-else-if="equipment"><div class="hero"><div><div class="eyebrow">设施设备巡检</div><h2>{{equipment.equipmentName}}</h2><p>{{equipment.equipmentCode}} · {{equipment.categoryName}}</p></div><el-tag size="large">{{statusText[equipment.equipmentStatus]||equipment.equipmentStatus}}</el-tag></div><el-card><template #header><b>设备基础信息</b></template><el-descriptions :column="isMobile?1:2" border><el-descriptions-item label="所属系统">{{equipment.systemName||'-'}}</el-descriptions-item><el-descriptions-item label="安装位置">{{equipment.installationLocation||'-'}}</el-descriptions-item><el-descriptions-item label="楼层/区域">{{[equipment.floorCode,equipment.areaName].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="品牌/型号">{{[equipment.brand,equipment.model].filter(Boolean).join(' / ')||'-'}}</el-descriptions-item><el-descriptions-item label="规格参数">{{equipment.specification||'-'}}</el-descriptions-item><el-descriptions-item label="出厂编号">{{equipment.serialNumber||'-'}}</el-descriptions-item><el-descriptions-item label="责任部门">{{equipment.responsibleDepartment||'-'}}</el-descriptions-item><el-descriptions-item label="责任人">{{equipment.responsiblePerson||'-'}} {{equipment.responsiblePhone||''}}</el-descriptions-item><el-descriptions-item v-for="f in baseFields" :key="f.key" :label="f.label">{{attributes[f.key]??'-'}} {{attributes[f.key]!=null&&f.unit?f.unit:''}}</el-descriptions-item></el-descriptions></el-card><el-card class="tasks"><template #header><b>当前待巡检任务</b></template><div v-for="t in equipment.pendingTasks" :key="t.id" class="task"><div><b>{{t.taskNo}}</b><p>计划时间：{{fmt(t.scheduledAt)}}　截止：{{fmt(t.dueAt)}}</p></div><el-button type="primary" @click="go(t)">进入巡检表单</el-button></div><el-empty v-if="!equipment.pendingTasks?.length" description="该设备当前没有待执行的计划任务"><p>设备已识别，可联系管理员检查巡检计划或发起专项巡检。</p></el-empty></el-card></template></div></template>
<script setup lang="ts">import{ref,computed,onMounted}from'vue';import{useRoute,useRouter}from'vue-router';import{inspectionEquipmentApi}from'@/api/inspectionEquipment';const route=useRoute(),router=useRouter(),equipment=ref<any>(),error=ref(''),isMobile=ref(window.innerWidth<768),statusText:any={IN_USE:'在用',MAINTENANCE:'维修中',OUT_OF_SERVICE:'停用',SCRAPPED:'报废'};const parse=(s:any,d:any)=>{try{return typeof s==='string'?JSON.parse(s):s||d}catch{return d}};const baseFields=computed(()=>parse(equipment.value?.baseFieldsJson,[])),attributes=computed(()=>parse(equipment.value?.attributesJson,{}));const fmt=(x:any)=>x?String(x).replace('T',' ').slice(0,19):'-';function go(t:any){router.replace(`/inspection/tasks?taskToken=${t.accessToken}`)}onMounted(async()=>{try{equipment.value=await inspectionEquipmentApi.scan(String(route.params.token));if(equipment.value.pendingTasks?.length===1)go(equipment.value.pendingTasks[0])}catch(e:any){error.value=e?.message||'无法读取设备资料'}})</script>
<style scoped>.scan{max-width:900px;margin:auto;padding:20px}.hero{display:flex;justify-content:space-between;align-items:center;background:linear-gradient(135deg,#164e63,#0f766e);color:#fff;padding:24px;border-radius:12px;margin-bottom:14px}.hero h2{margin:5px 0}.hero p{margin:0;opacity:.85}.eyebrow{font-size:13px;opacity:.8}.tasks{margin-top:14px}.task{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #eee;padding:12px 0}.task p{color:#777;margin:6px 0 0;font-size:13px}@media(max-width:768px){.scan{padding:10px}.task{display:block}.task .el-button{width:100%;margin-top:10px}}</style>
